from __future__ import annotations
from hashlib import sha256
import json
import os
from pathlib import Path
import re
import socket
import subprocess
import sys
import time

REPO = Path('${CBUS_REPOSITORY_ROOT}')
TK = REPO / 'toolkit-cli'
sys.path[:0] = [str(TK), str(TK / 'src')]
from research.cgate_session_differential import source_fingerprint as session_fingerprint
from research.cgate_tagged_session_differential import source_fingerprint as tagged_fingerprint
from research.cgate_dbsetxml_unit_differential import fingerprint as unit_fingerprint
from research.sanitize_evidence_receipts import sanitize, _validator, local_coordinate_fields

work = Path(sys.argv[1]).resolve()
mock, daemon = map(lambda value: Path(value).resolve(), sys.argv[2:4])
if work.exists() or not work.parent.is_dir():
    raise ValueError('Fresh raw root required')
work.mkdir(mode=0o700)
raw = work / 'raw'; raw.mkdir()
public = work / 'public-candidates'; public.mkdir()
archive = work / 'raw-archive'
python = TK / '.venv/bin/python'
environment = {k:v for k,v in os.environ.items() if not k.startswith('CBUS_') and k not in ('PYTHONHOME','PYTHONPATH')}
environment.update(PYTHONPATH=str(TK / 'src') + ':' + str(TK), PYTHONDONTWRITEBYTECODE='1')

def digest(path):
    return sha256(Path(path).read_bytes()).hexdigest()

def fingerprint():
    result = {}
    for name, function in (('session', session_fingerprint), ('tagged', tagged_fingerprint)):
        for product, daemon_flag in (('cgate-mock', False), ('cmqttd', True)):
            result[name + '/' + product] = function(daemon=daemon_flag)
    for product, daemon_flag in (('cgate-mock', False), ('cmqttd', True)):
        result['unit/' + product] = unit_fingerprint(daemon_flag)
    return result

def alive(pid):
    return bool(subprocess.run(['/bin/ps', '-p', str(pid), '-o', 'pid='], capture_output=True, text=True).stdout.strip())

def socket_closed(port):
    try:
        with socket.create_connection(('127.0.0.1', port), timeout=.2):
            return False
    except OSError:
        return True

manifest = {'driver_sha256': digest(Path(__file__)), 'source_before': fingerprint(), 'binary_before': {name: {'path': str(path), 'sha256': digest(path)}
            for name, path in (('cgate-mock', mock), ('cmqttd', daemon))}, 'runs': [], 'complete': False}
(work / 'raw-run-manifest.json').write_text(json.dumps(manifest, indent=2) + '\n')
commands = [
 ('session-mock', 'cgate_session_differential.py', ['--mock-bin', mock, '--output', raw / 'cgate-session-differential-fixed.json']),
 ('session-cmqttd', 'run_cgate_session_cmqttd_differential.py', ['--cmqttd-bin', daemon, '--output', raw / 'cgate-session-differential-cmqttd.json']),
 ('tagged-both', 'cgate_tagged_session_differential.py', ['--mock-bin', mock, '--cmqttd-bin', daemon, '--output-dir', raw]),
 ('unit-both', 'cgate_dbsetxml_unit_differential.py', ['--mock-bin', mock, '--cmqttd-bin', daemon, '--output-dir', raw]),
]
try:
    for label, script, arguments in commands:
        argv = [str(python), str(TK / 'research' / script), *map(str, arguments)]
        row = {'label': label, 'argv': argv, 'cwd': str(TK), 'environment': {'PYTHONPATH': environment['PYTHONPATH']},
               'source_before': fingerprint(), 'binary_before': {str(path): digest(path) for path in (mock, daemon)},
               'owned_children_observed': {}, 'child_observation_scope': 'only descendant PIDs of this owned producer'}
        manifest['runs'].append(row)
        with (work / (label + '.stdout')).open('wb') as stdout, (work / (label + '.stderr')).open('wb') as stderr:
            process = subprocess.Popen(argv, cwd=TK, env=environment, stdout=stdout, stderr=stderr)
            row['pid'] = process.pid
            while process.poll() is None:
                pending = [process.pid]
                seen = set()
                while pending:
                    pid = pending.pop()
                    if pid in seen:
                        continue
                    seen.add(pid)
                    children = subprocess.run(['${CBUS_SYSTEM_TOOLS}/bin/pgrep', '-P', str(pid)], capture_output=True, text=True).stdout.split()
                    pending.extend(int(value) for value in children if value.isdigit())
                    if pid == process.pid:
                        continue
                    command = subprocess.run(['/bin/ps', '-p', str(pid), '-o', 'command='], capture_output=True, text=True).stdout.strip()
                    if command.startswith((str(mock), str(daemon))):
                        child = row['owned_children_observed'].setdefault(str(pid), {'argv_ps': command, 'listening_ports': [], 'temporary_roots': []})
                        ports = subprocess.run(['${CBUS_SYSTEM_TOOLS}/sbin/lsof', '-nP', '-a', '-p', str(pid), '-iTCP', '-sTCP:LISTEN', '-Fn'],
                                               capture_output=True, text=True).stdout
                        for value in re.findall(r'^n127\.0\.0\.1:([0-9]+)$', ports, re.M):
                            if int(value) not in child['listening_ports']:
                                child['listening_ports'].append(int(value))
                        import shlex
                        tokens = shlex.split(command)
                        for index, value in enumerate(tokens[:-1]):
                            if value in ('--project-file', '--cgate-state'):
                                root = str(Path(tokens[index + 1]).parent)
                                if root not in child['temporary_roots']:
                                    child['temporary_roots'].append(root)
                time.sleep(.005)
            row['exit_status'] = process.wait()
            row['producer_waited'] = True
        for name in ('stdout', 'stderr'):
            path = work / (label + '.' + name)
            row[name] = {'path': str(path), 'sha256': digest(path), 'bytes': path.stat().st_size}
        for pid, child in row['owned_children_observed'].items():
            child['not_alive_after_producer_exit'] = not alive(int(pid))
            child['ports_closed_after_producer_exit'] = {str(port): socket_closed(port) for port in child['listening_ports']}
            child['temporary_roots_removed_after_producer_exit'] = {root: not Path(root).exists() for root in child['temporary_roots']}
        row['source_after'] = fingerprint()
        row['binary_after'] = {str(path): digest(path) for path in (mock, daemon)}
        if row['exit_status'] != 0 or row['source_before'] != row['source_after'] or row['binary_before'] != row['binary_after']:
            raise ValueError('Producer failed or inputs changed: ' + label)
        if any(not child['not_alive_after_producer_exit'] or not all(child['ports_closed_after_producer_exit'].values())
               or not all(child['temporary_roots_removed_after_producer_exit'].values()) for child in row['owned_children_observed'].values()):
            raise ValueError('Owned-child cleanup failed: ' + label)
        (work / 'raw-run-manifest.json').write_text(json.dumps(manifest, indent=2) + '\n')
    candidates = []
    for name, kind in (
       ('cgate-session-differential-fixed.json', 'session'), ('cgate-session-differential-cmqttd.json', 'session'),
       ('cgate-tagged-session-differential-mock.json', 'tagged'), ('cgate-tagged-session-differential-cmqttd.json', 'tagged'),
       ('cgate-dbsetxml-unit-differential-mock.json', 'unit'), ('cgate-dbsetxml-unit-differential-cmqttd.json', 'unit')):
        path = raw / name
        payload = path.read_bytes()
        _validator(kind)(json.loads(payload))
        published = sanitize(payload, kind=kind, private_raw_dir=archive)
        candidate = public / name; candidate.write_bytes(published)
        _validator(kind)(json.loads(published))
        if local_coordinate_fields(json.loads(published)):
            raise ValueError('Publication candidate contains private coordinates')
        candidates.append({'kind': kind, 'product': json.loads(payload)['product'], 'raw_path': str(path),
                           'raw_sha256': digest(path), 'candidate_path': str(candidate), 'candidate_sha256': digest(candidate),
                           'source_bindings': len(json.loads(payload)['source_fingerprint'])})
    manifest['source_after'] = fingerprint()
    if manifest['driver_sha256'] != digest(Path(__file__)):
        raise ValueError('Replay driver changed during execution')
    manifest['binary_after'] = {name: {'path': str(path), 'sha256': digest(path)} for name, path in (('cgate-mock', mock), ('cmqttd', daemon))}
    if manifest['source_before'] != manifest['source_after'] or manifest['binary_before'] != manifest['binary_after']:
        raise ValueError('Final closure changed during six replays')
    manifest['candidates'] = candidates
    manifest['complete'] = True
    manifest['cleanup_qualification'] = 'Producer terminal/wait observed for all four commands; PID/socket/scratch evidence covers only descendants sampled while alive, with missing fast children explicitly unsampled.'
except BaseException as error:
    manifest['error'] = {'type': type(error).__name__, 'message': str(error)}
    raise
finally:
    (work / 'raw-run-manifest.json').write_text(json.dumps(manifest, indent=2) + '\n')
print(json.dumps({'complete': manifest['complete'], 'candidates': len(manifest['candidates']), 'bindings': sum(row['source_bindings'] for row in manifest['candidates'])}))
